let pendulums = [];
let gravity = 2.5;
let maxV = 0;
let bg;
let bgCol = "#ede7d9";
let bgCola = "#ede7d920";
let lineCol = "#a49694";
let bgRot = 0;
let radius = 300.0;

function setup() 
{
	createCanvas(windowWidth, windowHeight);
	background(bgCol);
	stroke(lineCol);
	strokeWeight(2);

	flip();
}

function draw() 
{
//	background(bgCol);
//	bg.background(bgCola);
	image(bg,0,0,width,height);
	translate(width/2,height/2);
	rotate(bgRot);

	for(let p = 0; p < pendulums.length; p++)
	{
		pendulums[p].draw();
	}

//	if(frameCount%550==0)
//	{
//		flip();
//	}
}

function flip()
{
	bgRot = bgRot == 0 ? PI : 0;
	bg = createGraphics(width, height);
	bg.translate(width/2,height/2);
	bg.rotate(bgRot);
	bg.stroke(lineCol);
	bg.strokeWeight(2);

	let num = 50;
	let count = 0;
	let size = radius;
	for(let rack = 0; rack < num+200; rack++)
	{
		pendulums[count++] = new Pendulum(radius+5,0,(rack/num)*1000,1,PI+0.001,size,rack);
		pendulums[count++] = new Pendulum(-radius-5,0,(rack/num)*1000,1,PI-0.001,size,rack);
	}
	pendulums.reverse();
}

function Pendulum(cx,cy,l,m,a,s,n)
{
	this.f 	= 0;	this.d  = random(0.99);	//force, dampening
	this.x 	= cx;	this.y 	= cy; 	//pendulum attach pos x,y
	this.a 	= a; 	this.acc= 0;		//angle and acceleration
	this.v	= 0; 	this.l 	= l; 		//angular velocity and length
	this.bx = 0; 	this.by = 0;		//pendulum bob pos x,y
	this.px = 0; 	this.py = 0;		//previous bob pos x,y
	this.s 	= s;	this.m 	= m;		//size and mass
	this.n = n;

	this.draw = function()
	{
		let force = gravity * sin(this.a);
		this.acc = (-1 * force)/this.l;
		this.v += this.acc;
		this.a += this.v;
		this.v *= (this.d -= 0.0001);
		this.bx = (radius/2+this.l/10) * sin(this.a) + this.x;
		this.by = (radius/2+this.l/10) * cos(this.a) + this.y;
		noFill();
		stroke(this.n%2 ? bgCol : "#000000");
		strokeWeight(0.5);
		circle(this.bx,this.by,this.l/5);
		if(this.f)
		{
			bg.line(this.px,this.py,this.bx,this.by);
		}
		this.px = this.bx;
		this.py = this.by;
		this.f=1;
	}
}

